        stack=[b]; comp=[]
        while stack:
            cur=stack.pop(); comp.append(cur)
            R0,R1,C0,C1,S,n=cur
            for nb in info:
                R0b,R1b,C0b,C1b,Sb,nb=n
                if nb[4]!=mx or nb in seen: continue
                # adjacent: share a border edge
                if abs(R1-R0b)<=1 and C0==C0b and abs(C1-C1b)<=1: pass
                adj=False
                if (R0,R1) in ((nb[0],nb[1]),(nb[0]-1,nb[1]+2)) and (C0,C1)==(nb[2],nb[3]): adj=True
                if (C0,C1) in ((nb[0],nb[1]),(nb[0]-1,nb[1]+2)) and (R0,R1)==(nb[2],nb[3]): adj=True
                if adj:
                    if nb not in seen: stack.append(nb); seen.add(nb)
        comps.append(comp)
    out=[[bg]*W for _ in range(H)]
    for i in sr:
        for j in range(W): out[i][j]=sep
    for j in sc:
        for i in range(H): out[i][j]=sep
    for b in info:
        if b[4]==mx and b not in seen:
            R0,R1,C0,C1,S,n=b
            for i in range(R0,R1):
                for j in range(C0,C1): out[i][j]=n
